 const timer=useRef<any>(null),queue=useRef(Promise.resolve<any>(null)),latest=useRef(f),revision=useRef(0),savedRevision=useRef(0),mounted=useRef(true);latest.current=f;
 const done=f.status==='realizada',skills=data.skills.filter((s:any)=>s.studentId===f.studentId),activities=data.activities.filter((a:any)=>a.studentId===f.studentId||a.suggestedStudentIds?.includes(f.studentId)||(!a.studentId&&!a.suggestedStudentIds?.length));
